--## MONITORS ###
--###############

-- See https://wiki.hyprland.org/Configuring/Monitors/

-- monitor eDP - m1; monitor HDMI - m2; m1 + m2
-- M1 Down: 0x1080 + 0x0
-- M1 Up: 0x0 + 0x1080
-- M1 Right: 1920x0 + 0x0
-- M2 Left: 0x0 + 1920x0

-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.monitor({
    output = "eDP-1",
    mode = "1920x1080@60",
    position = "0x1080",
    scale = "1",
})

hl.monitor({
    output = "HDMI-A-2",
    mode = "1920x1080@60",
    position = "0x0",
    scale = "1",
})

